
#################
# 
# This script loads the SEM tables generated by fit_obspi.R and plots results
# NOTE: this script should be run from within each current_models dir
#
#################

source("~/Data/bgs_lmr/human_data/tools/HelperFunctions.R")

constrained_models <- c("split_cds_phastcons", "split_cds_regulatory")
mutation_maps <- c("carlson", "gnomad", "roulette")

#################
#
# Simple correlations (latent constructs for B, mu, r)
#
#################

# 10kb
pearson_10kb_models <- list(length=2)
for(i in 1:length(constrained_models)) {
  
  m <- constrained_models[i]
  pearson_10kb <- list(length=num_chrom)
  
  for(c in 1:num_chrom) {
    
    tmp <- fread(paste("sem/pearson_chr", c, "_", m, "_10kb.csv", sep=""))
    var_names <- setdiff(names(tmp), "V1")
    
    long <- tmp %>%
      pivot_longer(
        cols = -V1,
        names_to = "variable2",
        values_to = "value"
      ) %>%
      dplyr::rename(variable1 = V1) %>%
      filter(variable1 != variable2) %>%
      mutate(
        i = match(variable1, var_names),  
        j = match(variable2, var_names), 
        pair_key = paste(pmin(variable1, variable2), pmax(variable1, variable2), sep = "|")
      )
    
    # lower triangle: correlations
    corr_long <- long %>%
      filter(i > j, !is.na(value)) %>%
      transmute(
        pair_key,
        var1 = pmin(variable1, variable2),
        var2 = pmax(variable1, variable2),
        correlation = as.numeric(value)
      )
    
    # upper triangle: p-values
    pval_long <- long %>%
      filter(i < j, !is.na(value)) %>%
      transmute(
        pair_key,
        pvalue = as.numeric(value)
      )
    
    flat_matrix <- corr_long %>%
      left_join(pval_long, by = "pair_key") %>%
      arrange(., var1, var2)
    
    flat_matrix$chrom <- c
    pearson_10kb[[c]] <- flat_matrix
  }
  
  pearson_10kb <- do.call(rbind.data.frame, pearson_10kb)
  pearson_10kb$constrained_model <- m
  
  pearson_10kb_models[[i]] <- pearson_10kb
}

pearson_10kb_models <- data.table::rbindlist(pearson_10kb_models)
pearson_10kb_models$scale <- 1e+4

