pearson_1Mb_models$scale <- 1e+6

pearson_cors <- rbind.data.frame(pearson_10kb_models, pearson_100kb_models, pearson_1Mb_models) 

pearson_cors$constrained_model <- factor(pearson_cors$constrained_model,
                                         levels = names(elem_labels), 
                                         labels = unname(elem_labels))

for(var in unique(c(pearson_cors$var1, pearson_cors$var2))) {
  
  tbl <- pearson_cors %>% filter(., var1 == var | var2 == var) %>%
    mutate(v1 = var1, v2 = var2,                  
           var1 = if_else(v2 == var, v2, v1),            
           var2 = if_else(v2 == var, v1, v2)) %>% dplyr::select(-v1, -v2)
  
  tbl$sig <- tbl$pvalue < 0.05 / num_chrom
  
  p <- ggplot(data=tbl, aes(x=chrom, y=correlation, alpha=sig, color=var2)) +
    geom_point(size=3) + geom_hline(yintercept=0, linetype="dashed") +
    facet_grid(scale/1e3~constrained_model) + theme_classic() + 
    scale_y_continuous(breaks=pretty_breaks()) +
    scale_x_continuous(breaks=1:num_chrom) + 
    scale_alpha_manual(values = c("TRUE" = 1, "FALSE" = 0.35), 
                       labels=c("TRUE"="Significant", "FALSE"="Non-Significant"), name=NULL) +
    scale_color_manual(values=c("brown1", "cyan3", "purple3", "gold3"),
                       labels=c(B="B",
                                avg_mut=expression(mu),
                                avg_pi=expression(pi),
                                avg_rec="r",
                                prop_del_sites="E"),
                       name=NULL) +
    labs(title=NULL, x="Chromosome", y="Pearson correlation") +
    theme(strip.text.y=element_text(size=16),     
          strip.text.x=element_text(size=16),    
          axis.title=element_text(size=16), 
          axis.text=element_text(size=12), 
          axis.text.x=element_text(size=12),
          legend.text=element_text(size=16),
          legend.title=element_text(size=16),
          legend.position="bottom")
  save_plot(paste("sem/pearson_", var, ".pdf", sep=""), p, base_height=7, base_width=16)
}

#################
#
# Correlations with raw mutation maps instead of latent
#
#################

## reload
human_maps_10kb <- fread("maps/maps_10kb.csv.gz")
human_maps_100kb <- fread("maps/maps_100kb.csv.gz") 
human_maps_1Mb <- fread("maps/maps_1Mb.csv.gz")

# 10kb
pearson_10kb <- list(length=length(mutation_maps) * length(constrained_models) * num_chrom)
idx <- 1
for(u in mutation_maps) {
  for(m in constrained_models) {
    for(c in 1:num_chrom) {
      
      data <- filter(human_maps_10kb, mut_map==u, constrained_model==m, chrom==c, coverage >= 0.75) %>%
        dplyr::select(., avg_pi, prop_del_sites, B, avg_rec, avg_mut)
      n <- ncol(data)
      
      cor_mat <- matrix(NA, n, n)
      p_mat <- matrix(NA, n, n)
      colnames(cor_mat) <- rownames(cor_mat) <- colnames(data)
      colnames(p_mat) <- rownames(p_mat) <- colnames(data)
      
      for (i in 1:n) {
        for (j in 1:n) {
          test <- cor.test(data[[i]], data[[j]], method = "pearson", use = "complete.obs")
          cor_mat[i, j] <- test$estimate
          p_mat[i, j] <- test$p.value
        }
      }
      
      combined_mat <- matrix(NA_real_, n, n)
      for (i in 1:n) {
        for (j in 1:n) {
          if (i > j) {
            combined_mat[i, j] <- round(cor_mat[i, j], 4)
          } else if (i < j) {
            combined_mat[i, j] <- signif(p_mat[i, j], 3)
          }
        }
      }
      
      combined_mat <- setDT(as.data.frame(combined_mat))
      rownames(combined_mat) <- colnames(combined_mat) <- colnames(data)
      
      var_names <- names(combined_mat)
      combined_mat$V1 <- rownames(combined_mat)
      
      long <- combined_mat %>%
        pivot_longer(
          cols = -V1,
          names_to = "variable2",
          values_to = "value"
        ) %>%
        dplyr::rename(variable1 = V1) %>%
        filter(variable1 != variable2) %>%
        mutate(
          i = match(variable1, var_names), 
          j = match(variable2, var_names),  
          pair_key = paste(pmin(variable1, variable2), pmax(variable1, variable2), sep = "|")
        )
      
      corr_long <- long %>%
        filter(i > j, !is.na(value)) %>%
        transmute(
          pair_key,
          var1 = pmin(variable1, variable2),
          var2 = pmax(variable1, variable2),
          correlation = as.numeric(value)
        )
      
      pval_long <- long %>%
        filter(i < j, !is.na(value)) %>%
        transmute(
          pair_key,
          pvalue = as.numeric(value)
        )
      
      flat_matrix <- corr_long %>%
        left_join(pval_long, by = "pair_key") %>%
        arrange(., var1, var2)
      
      flat_matrix$chrom <- c
      flat_matrix$constrained_model <- m
      flat_matrix$mut_map <- u
      
      pearson_10kb[[idx]] <- flat_matrix
      idx <- idx + 1
    }
  }
}

pearson_10kb <- data.table::rbindlist(pearson_10kb)
pearson_10kb$scale <- 1e+4

