setDT(chr_r2_dags)
tab <- left_join(tbl_summaries, chr_r2_dags, by=c("scale", "chrom", "constrained_model"))

lm_list <- list(length=length(constrained_models) * length(unique(tab$scale)) * length(unique(tab$DAG)))
pos <- 1
for(const in unique(tab$constrained_model)) {
  for(scal in unique(tab$scale)) {
    for(dag in unique(tab$DAG)) {
      
      df_transf <- filter(tab, constrained_model==const, scale==scal, DAG==dag) %>%
        dplyr::select(., c(avg_pi, prop_del_sites_log, mut_latent_log, rec_latent_log, GC)) %>% setDT()
      
      df_transf <- apply(df_transf, 2, std_by_sd) %>% as.data.frame()
      setnames(df_transf, old=c("mut_latent_log", "rec_latent_log", "prop_del_sites_log"),
                          new=c("avg_mut", "avg_rec", "prop_del_sites"))
      
      meta_lm <- lm(data=df_transf, formula=avg_pi ~ GC + prop_del_sites + avg_mut + avg_rec)
      
      summ <- summary(meta_lm)
      
      coefs_df <- as.data.frame(summ$coefficients)
      coefs_df$term <- rownames(coefs_df)
      rownames(coefs_df) <- NULL
      names(coefs_df)[4] <- "p-value"
      
      coefs_df$constrained_model <- const
      coefs_df$scale <- scal
      coefs_df$DAG <- dag
      coefs_df$r2_lm <- summ$r.squared
      coefs_df$r2_adj_lm <- summ$adj.r.squared
      
      lm_list[[pos]] <- coefs_df %>% dplyr::select(., c("term", "Estimate", "p-value",
                                                      "constrained_model", "scale", "DAG", 
                                                      "r2_lm", "r2_adj_lm")) %>% filter(., term!="(Intercept)")
      pos <- pos + 1
    }
  }
}

coefs_df <- data.table::rbindlist(lm_list)
fwrite(setDT(coefs_df), paste("sem/obspi_lm_r2pi.csv", sep=""))

coefs_df$sig <- coefs_df$`p-value` < 0.05

n <- ggplot(data=filter(coefs_df, DAG==3 | DAG==4), 
            aes(x=term, y=Estimate, alpha=sig, color=as.factor(DAG))) +
  geom_point(size=3.5) +
  facet_grid(scale/1e3~constrained_model) + theme_classic() + 
  scale_x_discrete(labels=c("avg_mut"=expression(mu),
                            "avg_rec"="r",
                            "GC"="GC",
                            "prop_del_sites"="E")) +
  scale_y_continuous(breaks=pretty_breaks()) +
  scale_alpha_manual(values = c("TRUE" = 1, "FALSE" = 0.35), 
                     labels=c("TRUE"="Significant", "FALSE"="Non-Significant"), name=NULL) +
  scale_color_manual(values=c("brown1", "cyan3"), name="DAG") +
  labs(title=NULL, x="Feature", y="Linear Coefficient") +
  theme(strip.text.y=element_text(size=16),
        strip.text.x=element_text(size=16),
        axis.title=element_text(size=16), 
        axis.text=element_text(size=18), 
        legend.text=element_text(size=16),
        legend.title=element_text(size=16),
        legend.position="bottom")
save_plot("sem/lm_chr_featrures_r2pi.pdf", n, base_height=8, base_width=14)

